
// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// 不要用 env("DATABASE_URL")：它在變數缺失時直接拋 PrismaConfigEnvError，
// 而 CI（fresh clone、.env 被 gitignore）只需要 prisma generate 產 client，
// 根本不連 DB。給一個惰性 fallback，讓 generate 在無 env 的環境也能跑；
// 真正要連線的 migrate/studio 仍以實際 DATABASE_URL 為準。
const databaseUrl = process.env.DATABASE_URL ?? "file:./prisma/dev.db";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  engine: "classic",
  datasource: {
    url: databaseUrl,
  },
  // NoteFts 是 FTS5 虛擬表，Prisma schema 表達不了（連帶的 _config/_data/_idx 等影子表也一樣）。
  // 不宣告成 external 的話，migrate dev 會把它當成 drift 而想 DROP，進而誘發 reset 清掉使用者筆記。
  experimental: { externalTables: true },
  tables: {
    external: [
      "NoteFts",
      "NoteFts_config",
      "NoteFts_content",
      "NoteFts_data",
      "NoteFts_docsize",
      "NoteFts_idx",
    ],
  },
});
